votes.sql:
WITH team_counts AS (
    SELECT p."publisher_name" AS team, COUNT(s.id) AS member_count
    FROM "superhero" s
    JOIN "publisher" p ON s.publisher_id = p.id
    GROUP BY p."publisher_name"
)
SELECT team
FROM team_counts
WHERE member_count = (SELECT MAX(member_count) FROM team_counts);
}

